public int kthSmallest(int[] nums, int k) {
    PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
    for (int x : nums) {
        maxHeap.offer(x);
        if (maxHeap.size() > k) {
            maxHeap.poll();      // drop the largest — it can't be in the k smallest
        }
    }
    return maxHeap.peek();       // top of a size-k max-heap is the kth smallest
}

