import heapq

def kth_smallest(self, nums: list[int], k: int) -> int:
    max_heap: list[int] = []          # store negatives to fake a max-heap
    for x in nums:
        heapq.heappush(max_heap, -x)
        if len(max_heap) > k:
            heapq.heappop(max_heap)   # pops -largest → drops the largest x
    return -max_heap[0]               # negated top is the kth smallest

