import random

def kth_smallest(self, nums: list[int], k: int) -> int:
    target = k - 1
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        p = self._partition(nums, lo, hi)
        if p == target:
            return nums[p]
        if p < target:
            lo = p + 1        # kth smallest is to the right
        else:
            hi = p - 1        # kth smallest is to the left
    return -1                 # unreachable for valid k

def _partition(self, nums: list[int], lo: int, hi: int) -> int:
    r = random.randint(lo, hi)
    nums[r], nums[hi] = nums[hi], nums[r]   # random pivot guards worst case
    pivot, i = nums[hi], lo
    for j in range(lo, hi):
        if nums[j] < pivot:
            nums[i], nums[j] = nums[j], nums[i]
            i += 1
    nums[i], nums[hi] = nums[hi], nums[i]   # pivot to its final sorted slot
    return i

